<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']); include __DIR__.'/dbconnection.php';$id=(int)($_GET['patient_id']??0);$patient=null;if($id){$r=$con->query("SELECT * FROM patient WHERE patientid=$id");$patient=$r?$r->fetch_assoc():null;}$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$appointments=$id?$con->query("SELECT a.*,d.doctorname FROM appointment a LEFT JOIN doctor d ON d.doctorid=a.doctorid WHERE a.patientid=$id ORDER BY a.appointmentid DESC LIMIT 50"):null;$treatments=$id?$con->query("SELECT * FROM treatment_records WHERE patientid=$id ORDER BY treatmentrecordid DESC LIMIT 50"):null;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Medical Records</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">MEDICAL RECORDS</span><h1>Patient Medical Record</h1><p>One place for visits, doctors, diagnoses, prescriptions, laboratory, admissions and payments.</p></div></div><div class="panel"><form method="get" class="form-grid"><label>Select patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>" <?=$id===$p['patientid']?'selected':''?>><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><button class="primary-btn">Open record</button></form></div><?php if($patient):?><div class="panel"><h2><?=esc($patient['patientname'])?></h2><p class="muted">ID: <?=$patient['patientid']?> · Mobile: <?=esc($patient['mobileno'])?> · Blood group: <?=esc($patient['bloodgroup'])?> · Gender: <?=esc($patient['gender'])?></p><h3>Visits / Appointments</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Doctor</th><th>Status</th></tr></thead><tbody><?php if($appointments)while($r=$appointments->fetch_assoc()):?><tr><td><?=esc($r['appointmentdate']??$r['appointmentid'])?></td><td><?=esc($r['doctorname']??'')?></td><td><?=esc($r['status']??'')?></td></tr><?php endwhile;?></tbody></table></div><h3>Treatment history</h3><div class="table-wrap"><table><thead><tr><th>Record</th><th>Date</th><th>Details</th></tr></thead><tbody><?php if($treatments)while($r=$treatments->fetch_assoc()):?><tr><td><?=$r['treatmentrecordid']?></td><td><?=esc($r['date']??$r['treatmentdate']??'')?></td><td><?=esc(json_encode($r,JSON_UNESCAPED_UNICODE))?></td></tr><?php endwhile;?></tbody></table></div></div><?php endif;?></div></body></html>
